from datetime import datetime


def load_closes(text):
    pairs = []
    for row in csv.DictReader(text.splitlines()):
        when = datetime.strptime(row["date"], "%d/%m/%Y")
        try:
            close = float(row["close"])
        except ValueError:
            continue
        pairs.append((when, close))
    pairs.sort()
    return [(when.strftime("%Y-%m-%d"), close) for when, close in pairs]

