import random


def share_above(paths, days, seed):
    random.seed(seed)
    above = 0
    for _ in range(paths):
        price = 100.0
        for _ in range(days):
            price *= random.choice([0.99, 1.01])
        if price > 100.0:
            above += 1
    return above / paths

