from datetime import datetime


class Trade:
    def __init__(self, day, ticker, qty, price):
        if qty == 0:
            raise ValueError("a trade needs a non-zero quantity")
        self.when = datetime.strptime(day, "%d/%m/%Y")
        self.ticker = ticker
        self.qty = qty
        self.price = price


class Book:
    def __init__(self):
        self.trades = []

    def add(self, trade):
        self.trades.append(trade)

    def net(self, ticker):
        total = 0
        for t in self.trades:
            if t.ticker == ticker:
                total += t.qty
        return total

    def history(self):
        rows = sorted((t.when, t.ticker, t.qty) for t in self.trades)
        return [(when.strftime("%Y-%m-%d"), ticker, qty) for when, ticker, qty in rows]

