import csv


class Position:
    history = []

    def __init__(self, ticker, qty, avg_price):
        self.ticker = ticker
        self.qty = qty
        self.avg_price = avg_price

    def value(self, price):
        self.history.append(price)
        return self.qty * price


def load(text):
    out = []
    for row in csv.DictReader(text.splitlines()):
        try:
            out.append(Position(row["ticker"], row["qty"], row["avg_price"]))
        except:
            pass
    return out


def biggest(positions):
