class Account:
    def __init__(self, opening=0.0):
        self.pence = round(opening * 100)
        self.moves = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError(f"a deposit must be above zero: {amount}")
        p = round(amount * 100)
        self.pence = self.pence + p
        self.moves.append(p)

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError(f"a withdrawal must be above zero: {amount}")
        p = round(amount * 100)
        if p > self.pence:
            raise ValueError(f"only £{self.pence / 100:.2f} to withdraw from")
        self.pence = self.pence - p
        self.moves.append(-p)

    def balance(self):
        return self.pence / 100

    def history(self):
        return [p / 100 for p in self.moves]

